import http from 'k6/http';

export const options = {
  vus: 1,
  iterations: 1,
};

const baseUrl = __ENV.BASE_URL.replace(/\/+$/, '');

function requireSuccess(response, step) {
  if (response.status < 200 || response.status >= 300) {
    throw new Error(`${step} failed (HTTP ${response.status})`);
  }
}

export default function () {
  const jsonHeaders = { 'Content-Type': 'application/json' };

  const login = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: jsonHeaders },
  );
  requireSuccess(login, 'Login');

  const csrf = login.json('csrf');
  if (typeof csrf !== 'string' || csrf.length === 0) {
    throw new Error('Login response did not contain a CSRF token');
  }

  // k6 automatically sends the session cookie from this VU's cookie jar.
  requireSuccess(http.get(`${baseUrl}/products`), 'Product listing');

  const sessionHeaders = {
    ...jsonHeaders,
    'X-CSRF-Token': csrf,
  };

  const cart = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    { headers: sessionHeaders },
  );
  requireSuccess(cart, 'Add to cart');

  const checkout = http.post(`${baseUrl}/checkout`, '{}', {
    headers: sessionHeaders,
  });
  requireSuccess(checkout, 'Checkout');
}
