import { check, fail } from 'k6';
import http from 'k6/http';

const baseUrl = __ENV.BASE_URL.replace(/\/+$/, '');

export const options = {
  scenarios: {
    checkout: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 1,
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function requireSuccess(response, step) {
  if (!check(response, {
    [`${step} returns 2xx`]: (r) => r.status >= 200 && r.status < 300,
  })) {
    fail(`${step} failed with status ${response.status}`);
  }
}

export default function () {
  const login = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 },
  );
  requireSuccess(login, 'Login');

  let csrf;
  try {
    csrf = login.json('csrf');
  } catch (_) {
    // An invalid JSON response fails the token check below.
  }
  if (!check(csrf, {
    'Login returns a CSRF token': (token) =>
      typeof token === 'string' && token.length > 0,
  })) {
    fail('Login did not return a valid CSRF token');
  }

  // k6 automatically stores and sends session cookies in each VU's cookie jar.
  requireSuccess(http.get(`${baseUrl}/products`, { redirects: 0 }), 'Products');

  const postParams = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
  };

  requireSuccess(
    http.post(`${baseUrl}/cart`, JSON.stringify({ product_id: 'sku-1' }), postParams),
    'Cart',
  );
  requireSuccess(
    http.post(`${baseUrl}/checkout`, JSON.stringify({}), postParams),
    'Checkout',
  );
}
